import json
from datetime import datetime, timezone
from pathlib import Path

def utc(value):
    dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    return dt.astimezone(timezone.utc)

records = []
for source_file in ("message.json", "trace.json", "audit.json", "endpoint.json"):
    path = Path(source_file)
    if not path.exists():
        continue
    value = json.loads(path.read_text(encoding="utf-8"))
    values = value if isinstance(value, list) else [value]
    for item in values:
        if item.get("event_time_utc"):
            records.append({
                "time_utc": utc(item["event_time_utc"]).isoformat(),
                "source": source_file,
                "event_type": item.get("event_type"),
                "evidence_id": item.get("evidence_id")
            })

records.sort(key=lambda x: x["time_utc"])
Path("incident_timeline.json").write_text(json.dumps(records, indent=2), encoding="utf-8")
print("events:", len(records))

