import unittest
from email_forensics import sha256_bytes, parse_timestamp

class TestEmailForensics(unittest.TestCase):
    def test_hash(self):
        self.assertEqual(
            sha256_bytes(b"abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        )
    def test_time(self):
        self.assertEqual(
            parse_timestamp("Tue, 08 Sep 2026 12:00:00 +0000"),
            "2026-09-08T12:00:00+00:00"
        )
    def test_bad_time(self):
        self.assertEqual(parse_timestamp("not a date"), "UNPARSED")

if __name__ == "__main__":
    unittest.main()
